// src/endpoints/stkPush.ts

import { DarajaClient } from "../client.js";
import { DarajaError } from "../error.js";
import { DarajaErrorResponse, StkPushRequest } from "../types.js";
import { getTimestamp } from "../utils.js";

function getPassword(
  shortcode: string,
  passkey: string,
  timestamp: string,
): string {
  return Buffer.from(`${shortcode}${passkey}${timestamp}`).toString("base64");
}

export async function stkPush(client: DarajaClient, request: StkPushRequest) {
  const token = await client.getAccessToken();
  const timestamp = getTimestamp();
  const password = getPassword(
    client.getConfig().shortcode,
    client.getConfig().passkey,
    timestamp,
  );

  const body = {
    BusinessShortCode: client.getConfig().shortcode,
    Password: password,
    Timestamp: timestamp,
    TransactionType: "CustomerPayBillOnline",
    Amount: request.amount,
    PartyA: request.phone,
    PartyB: client.getConfig().shortcode,
    PhoneNumber: request.phone,
    CallBackURL: request.callbackURL,
    AccountReference: request.accountReference,
    TransactionDesc: request.transactionDesc,
  };

  const response = await fetch(
    `${client.getBaseURL()}/mpesa/stkpush/v1/processrequest`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    },
  );
  const data = (await response.json()) as DarajaErrorResponse;

  if (!response.ok) {
    throw new DarajaError(data.errorCode, data.errorMessage, data.requestId);
  }

  return data;
}
