import { AuthorizationResponse, DarajaConfig } from "./types.js";
import "dotenv/config";
import { stkPush } from "./endpoints/stk-push.js";

export class DarajaClient {
  private config: DarajaConfig;
  private baseURL: string;
  private accessToken: string | null = null;
  private tokenExpiry: number | null = null;

  private validateConfig(config: DarajaConfig) {
    if (!config.consumerKey) throw new Error("Missing DARAJA_CONSUMER_KEY");

    if (!config.consumerSecret)
      throw new Error("Missing DARAJA_CONSUMER_SECRET");

    if (!config.shortcode) throw new Error("Missing DARAJA_SHORTCODE");

    if (!config.passkey) throw new Error("Missing DARAJA_PASSKEY");
  }

  constructor(config?: DarajaConfig) {
    const finalConfig = config || {
      consumerKey: process.env.DARAJA_CONSUMER_KEY!,
      consumerSecret: process.env.DARAJA_CONSUMER_SECRET!,
      shortcode: process.env.DARAJA_SHORTCODE!,
      passkey: process.env.DARAJA_PASSKEY!,
      environment:
        (process.env.DARAJA_ENVIRONMENT as "sandbox" | "production") ||
        "sandbox",
    };

    this.validateConfig(finalConfig);

    this.config = finalConfig;

    this.baseURL =
      this.config.environment === "production"
        ? "https://api.safaricom.co.ke"
        : "https://sandbox.safaricom.co.ke";
  }

  // -------------------------------
  // Token management
  // -------------------------------
  public async getAccessToken(): Promise<string> {
    const now = Date.now();

    if (this.accessToken && this.tokenExpiry && now < this.tokenExpiry) {
      return this.accessToken;
    }

    const url = `${this.baseURL}/oauth/v1/generate?grant_type=client_credentials`;
    const credentials = Buffer.from(
      `${this.config.consumerKey}:${this.config.consumerSecret}`,
    ).toString("base64");

    const response = await fetch(url, {
      method: "GET",
      headers: { Authorization: `Basic ${credentials}` },
    });

    if (!response.ok) throw new Error("Failed to generate access token");

    const data: AuthorizationResponse =
      (await response.json()) as AuthorizationResponse;

    this.accessToken = data.access_token;
    this.tokenExpiry = now + parseInt(data.expires_in, 10) * 1000 - 5000;

    return this.accessToken;
  }

  // -------------------------------
  // Internal helpers
  // -------------------------------
  public getConfig() {
    return this.config;
  }

  public getBaseURL() {
    return this.baseURL;
  }
  public stkPush(request: any) {
    return stkPush(this, request);
  }
}
